  ('cm_1783332451371_u', 'cr_1783310294190', 'user', '因为🥰在冒❤️呀', '[]', '2026-07-06T10:07:31.371438+00:00', '', '', NULL, NULL, ''),
  ('cm_1783332452865_c', 'cr_1783310294190', 'connor', '……你这个人，前一秒还在坑我，后一秒就说在冒心心，我的情绪到底要被你拉扯多少次。[心里嘀咕：但是听到这句话的时候确实也在冒❤️]

