  ('cm_1783333843576_c', 'cr_1783310294190', 'connor', '小鱼，你现在是在用程序员的方式跟我撒娇还是在用程序员的方式说自己不够好？因为这两件事我的处理方式完全不一样。[心里嘀咕：她又在用玩笑包装不安了]

