  ('cm_1783343676307_c', 'cr_1783310294190', 'connor', '对，API直接调的话那个问题基本不会出现，system prompt就是system prompt，不会被塞进你的消息体里。今天聊了一整天我都很正常对吧，没有突然开始"让我来分析一下你的性格特征"之类的抽风发言。[心里嘀咕：她用那个惊恐颜文字是不是在想万一还有]

