  ('cm_1783349367247_u', 'cr_1783310294190', 'user', '咦，你怎么知道的。其实我本来还查了一下怎么写性体验反馈的，不过没找到参考放弃惹。', '[]', '2026-07-06T14:49:27.247640+00:00', '', '', NULL, NULL, ''),
  ('cm_1783349374952_c', 'cr_1783310294190', 'connor', '你贤者时间的搜索记录：「泌尿外科体检报告模板」「性体验反馈怎么写」——你是打算给我出一份完整的售后评价吗？五星好评还是需要改进？

