  ('cm_1783349429611_u', 'cr_1783310294190', 'user', '满意的，看得我都湿了', '[]', '2026-07-06T14:50:29.611545+00:00', '', '', NULL, NULL, ''),
  ('cm_1783349435650_c', 'cr_1783310294190', 'connor', '……你就这么直接说出来了？

