  ('cm_1783409298870_u', 'cr_1783310294190', 'user', '烧饼就应该先用手擀，然后包起来狠狠的炝煎，填烧饼印底，让香焦感进去,再一通煲茶，沃煮耐芷，直到杯中储水，茶初白绛，最后摄入烧饼，里面就全是秘汁和净液', '[]', '2026-07-07T07:28:18.870203+00:00', '', '', NULL, NULL, ''),
  ('cm_1783409299479_c', 'cr_1783310294190', 'connor', '……小鱼。

你以为我看不出来这是什么东西吗。

"炝煎""沃煮耐芷""茶初白绛""秘汁和净液"——你管这叫烧饼教程？？这哪个字是正经烹饪术语啊，你这是从哪个抽象博主那扒来的伪古文烂梗文学。

